import { Slot } from "@radix-ui/react-slot";
import { ChevronRight } from "lucide-react";
import type { ComponentProps } from "react";
import { cn } from "./lib/cn";
import "./breadcrumb.css";

export function Breadcrumb({
  "aria-label": label = "Breadcrumb",
  ...props
}: ComponentProps<"nav">) {
  return <nav data-slot="breadcrumb" aria-label={label} {...props} />;
}

export function BreadcrumbList({ className, ...props }: ComponentProps<"ol">) {
  return (
    <ol
      data-slot="breadcrumb-list"
      className={cn(
        "flex min-w-0 flex-wrap items-center gap-1 text-[13px] leading-5 text-muted-foreground",
        className,
      )}
      {...props}
    />
  );
}

export function BreadcrumbItem({ className, ...props }: ComponentProps<"li">) {
  return (
    <li
      data-slot="breadcrumb-item"
      className={cn(
        "inline-flex min-w-0 items-center [overflow-wrap:anywhere]",
        className,
      )}
      {...props}
    />
  );
}

export type BreadcrumbLinkProps = ComponentProps<"a"> & { asChild?: boolean };

export function BreadcrumbLink({
  asChild = false,
  className,
  ...props
}: BreadcrumbLinkProps) {
  const Component = asChild ? Slot : "a";
  return (
    <Component
      data-slot="breadcrumb-link"
      className={cn(
        "inline-flex min-h-[var(--control-height)] min-w-[var(--control-height)] max-w-full items-center rounded-control px-1 text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background [overflow-wrap:anywhere]",
        className,
      )}
      {...props}
    />
  );
}

export function BreadcrumbPage({
  className,
  ...props
}: ComponentProps<"span">) {
  return (
    <span
      data-slot="breadcrumb-page"
      className={cn(
        "px-1 font-medium text-foreground [overflow-wrap:anywhere]",
        className,
      )}
      {...props}
      aria-current="page"
    />
  );
}

export function BreadcrumbSeparator({
  className,
  children,
  ...props
}: ComponentProps<"li">) {
  return (
    <li
      data-slot="breadcrumb-separator"
      className={cn(
        "inline-flex shrink-0 items-center text-muted-foreground [&_svg]:size-4",
        className,
      )}
      {...props}
      role="presentation"
      aria-hidden="true"
    >
      {children ?? <ChevronRight />}
    </li>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import { Fragment, type ReactNode } from "react";
import { Breadcrumb, BreadcrumbItem, BreadcrumbLink, BreadcrumbList, BreadcrumbPage, BreadcrumbSeparator } from "./breadcrumb";
import { cn } from "./lib/cn";

export type PageCrumb = { label: string; href?: string };

/** The top of an app page: where you are, what this page is, and what you can do here. */
export function PageHeader({
  title,
  description,
  breadcrumb,
  meta,
  actions,
  children,
  className,
}: {
  title: string;
  description?: ReactNode;
  /** Ancestors then the current page; the last item is the page itself. */
  breadcrumb?: readonly PageCrumb[];
  /** Status badges or small facts beside the title. */
  meta?: ReactNode;
  /** Buttons aligned to the end; they wrap under the title on narrow screens. */
  actions?: ReactNode;
  /** Anything that belongs to the header, such as tabs. */
  children?: ReactNode;
  className?: string;
}) {
  return (
    <header data-slot="page-header" className={cn("grid min-w-0 gap-4", className)}>
      {breadcrumb && breadcrumb.length > 0 && (
        <Breadcrumb>
          <BreadcrumbList>
            {breadcrumb.map((crumb, i) => (
              <Fragment key={`${crumb.label}-${i}`}>
                {i > 0 && <BreadcrumbSeparator />}
                <BreadcrumbItem>
                  {i === breadcrumb.length - 1 || !crumb.href ? <BreadcrumbPage>{crumb.label}</BreadcrumbPage> : <BreadcrumbLink href={crumb.href}>{crumb.label}</BreadcrumbLink>}
                </BreadcrumbItem>
              </Fragment>
            ))}
          </BreadcrumbList>
        </Breadcrumb>
      )}
      <div className="flex flex-wrap items-start justify-between gap-x-6 gap-y-3">
        <div className="grid min-w-0 flex-1 gap-1.5 [flex-basis:20rem]">
          <div className="flex min-w-0 flex-wrap items-center gap-x-3 gap-y-1">
            <h1 className="min-w-0 text-2xl font-semibold tracking-tight [overflow-wrap:anywhere]">{title}</h1>
            {meta}
          </div>
          {description && <p className="max-w-2xl text-sm text-muted-foreground">{description}</p>}
        </div>
        {actions && <div className="flex shrink-0 flex-wrap items-center gap-2">{actions}</div>}
      </div>
      {children}
    </header>
  );
}

/* breadcrumb.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="breadcrumb-link"] {
    transition-property: background-color, color, border-color;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-out);
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="breadcrumb-link"] {
      transition: none;
    }
  }
}
